WITH latest AS (SELECT * FROM transactions QUALIFY ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY amount DESC, id) = 1) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, CASE WHEN amount >= 3600 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, merchant, SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) AS debit_amount, MIN(txn_time) AS first_seen, SUM(amount) FILTER (WHERE txn_type = 'CREDIT') AS credit_total_amount, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, ROUND(AVG(amount), 2) AS avg_amount, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes FROM latest GROUP BY 1, 2, 3;
